from taf.internal.robot_typecasts import to_boolean
from taf.rfrl.procedures.resources.python.blackbox.exceptions import BlackboxBtsAlarmHistoryError, \
    BlackboxVoltageDataError
from taf.rfrl.procedures.resources.python.blackbox.rmod_blackbox import RmodBlackbox

from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger


class RuBlackbox(RmodBlackbox):
    def __init__(self, verify_structure: bool = True, verify_alarm: bool = True, verify_voltage: bool = True):
        super().__init__()
        self.blackbox_verification_methods = self._get_blackbox_methods()
        self.blackbox_verification_passed = True
        self.verify_alarm = to_boolean(verify_alarm)
        self.verify_structure = to_boolean(verify_structure)
        self.verify_voltage = to_boolean(verify_voltage)

    @method_decorator()
    def verify_structure_correctness(self):
        if self.verify_structure:
            super().verify_structure_correctness()

    @method_decorator()
    def verify_alarm_history_format(self):
        if not self.verify_alarm:
            return
        bts_alarm_part = False
        for line in self._bbox_lines:
            if 'Item type: BtsAlarmHistory' in line:
                bts_alarm_part = True
                continue
            if bts_alarm_part:
                if len(line) == 0:
                    continue
                if '---' in line:
                    break
                test_logger(line, "DEBUG")
                if line.count(",") != 7:
                    raise BlackboxBtsAlarmHistoryError(
                        f'BTS alarm history format is not correct: {self._path}.')
        if not bts_alarm_part:
            raise BlackboxBtsAlarmHistoryError(f'BTS alarm history not found in blackbox file: {self._path}')

    @method_decorator()
    def verify_voltage_histogram_samples(self):
        if not self.verify_voltage:
            return
        number_of_current_samples = ""
        number_of_last_samples = ""
        voltage_part = False
        raise_error = False
        for line in self._bbox_lines:
            if 'Item type: Voltage' in line:
                voltage_part = True
            if voltage_part:
                if len(line) == 0 or "---" in line:
                    continue
                if line.startswith("Item type: ") and "Voltage" not in line:
                    break
                test_logger(line, "DEBUG")
                if line.startswith("Values:"):
                    number_of_current_samples = line.split(" ")
                    number_of_current_samples = [el for el in number_of_current_samples if el][1]
                    continue
                if line.startswith("Last days 90:"):
                    number_of_last_samples = line.split(" ")
                    number_of_last_samples = [el for el in number_of_last_samples if el][3]
                    continue
                if number_of_current_samples and number_of_last_samples:
                    if int(number_of_current_samples) < int(number_of_last_samples):
                        raise_error = True
        if raise_error:
            raise BlackboxVoltageDataError(f'Voltage data is not correct in blackbox file: {self._path}')

    @method_decorator()
    def verify_blackbox(self, serial_number: str):
        self.blackbox_verification_passed = True
        for blackbox_verification in self.blackbox_verification_methods:
            try:
                blackbox_verification()
            except Exception as e:
                test_logger(f"[{serial_number}] {str(e)}", "ERROR")
                self.blackbox_verification_passed = False

    def _get_blackbox_methods(self):
        return [
            self.verify_alarm_history_format,
            self.verify_structure_correctness,
            self.verify_voltage_histogram_samples
        ]
